// 用 Vite JS API 计时各阶段：transform 累计 vs render/buildBundle 阶段，不修改仓库文件。
import { build } from "../node_modules/vite/dist/node/index.js";

const t0 = Date.now();
let transformCum = 0;
let transformCount = 0;
let renderStartAt = 0;
let writeAt = 0;

const timer = {
  name: "phase-timer",
  enforce: "pre",
  async transform(code, id) {
    const s = process.hrtime.bigint();
    // 不能在这里包住真正的转换，只能记录插件 hook 数量作为参考；真正转换由后续插件完成。
    return null;
  },
  buildStart() {
    console.log(`[phase] buildStart @ ${Date.now() - t0}ms`);
  },
  renderStart() {
    renderStartAt = Date.now() - t0;
    console.log(`[phase] renderStart @ ${renderStartAt}ms  (transform phase ended)`);
  },
  writeBundle() {
    writeAt = Date.now() - t0;
    console.log(`[phase] writeBundle @ ${writeAt}ms  (render phase: ${writeAt - renderStartAt}ms)`);
    console.log(`[phase] TOTAL ${Date.now() - t0}ms`);
  },
};

const cfg = await import("../zhi2-web-admin/vite.config.js");
const resolved = await cfg.default({ mode: "production", command: "build" });
resolved.plugins = [timer, ...(resolved.plugins || [])];
await build(resolved);

// 用 Vite 官方 loadConfigFromFile 加载真实配置（正确处理 __dirname 等），再注入阶段计时插件。
import { build, loadConfigFromFile } from "../node_modules/vite/dist/node/index.js";

const t0 = Date.now();
let renderStartAt = 0;

const timer = {
  name: "phase-timer",
  enforce: "pre",
  buildStart() {
    console.log(`[phase] buildStart @ ${Date.now() - t0}ms`);
  },
  renderStart() {
    renderStartAt = Date.now() - t0;
    console.log(`[phase] renderStart @ ${renderStartAt}ms (transform ended)`);
  },
  writeBundle() {
    const now = Date.now() - t0;
    console.log(`[phase] writeBundle @ ${now}ms (render: ${now - renderStartAt}ms)`);
    console.log(`[phase] TOTAL ${now}ms`);
  },
};

const loaded = await loadConfigFromFile(
  { command: "build", mode: "production" },
  "../zhi2-web-admin/vite.config.js",
  "../zhi2-web-admin"
);
const cfg = loaded.config;
cfg.plugins = [timer, ...(cfg.plugins || [])];
await build(cfg);

// 临时消融配置：包装真实 config，按 ABLATE 环境变量开关覆盖。不修改仓库文件。
import base from "../zhi2-web-admin/vite.config.js";
import { createSvgIconsPlugin } from "../node_modules/vite-plugin-svg-icons/dist/index.mjs";

const ABL = process.env.ABLATE || "";

export default async (env) => {
  const cfg = await base(env);

  if (ABL.includes("nominify") && cfg.build) {
    cfg.build.minify = false;
    cfg.build.cssMinify = false;
  }

  if (ABL.includes("novis") && Array.isArray(cfg.plugins)) {
    cfg.plugins = cfg.plugins.filter((p) => !(p && String(p.name).includes("visualizer")));
  }

  if (ABL.includes("nopreservesymlinks") && cfg.resolve) {
    cfg.resolve.preserveSymlinks = false;
  }

  // 关闭 svg-icons 的 SVGO：重建 svg 插件但 svgoOptions=false
  if (ABL.includes("nosvgo") && Array.isArray(cfg.plugins)) {
    cfg.plugins = cfg.plugins.map((p) => {
      if (p && p.name === "vite:svg-icons") {
        return createSvgIconsPlugin({
          iconDirs: [new URL("../zhi2-web-admin/public/assets/images/svg", import.meta.url).pathname.replace(/^\//, "")],
          symbolId: "icon-[dir]-[name]",
          svgoOptions: false,
        });
      }
      return p;
    });
  }

  return cfg;
};

